   List<string> inputs=new List<string>{"Predeterminada de Windows","Sin entrada (reproducción / importación)"};inputs.AddRange(NativeAudio.Devices(true));List<string> outputs=new List<string>{"Predeterminada de Windows"};outputs.AddRange(NativeAudio.Devices(false));audioIn=grid.Choice("Entrada de audio",inputs.ToArray(),staged.InputDevice==-2?1:staged.InputDevice<0?0:staged.InputDevice+2,delegate{});audioOut=grid.Choice("Salida de audio",outputs.ToArray(),staged.OutputDevice+1,delegate{});buffer=grid.Choice("Tamaño de búfer",new string[]{"256 frames · menor latencia","512 frames · equilibrado","1024 frames · mayor estabilidad"},staged.BufferFrames==256?0:staged.BufferFrames==1024?2:1,delegate{});autoLatency=grid.Bool("Compensar latencia automáticamente",staged.AutoLatencyCompensation,delegate{});compensation=grid.Number("Ajuste adicional de overdub (ms)",staged.LatencyCompMs,-500,500,delegate{},0);
