   Button apply=Theme.Button("APLICAR Y REINICIAR AUDIO / MIDI",Apply);apply.Width=350;grid.Row("Conexión",apply);midiStatus=Theme.Label("");midiStatus.MaximumSize=new Size(750,0);grid.Row("Estado",midiStatus);grid.Note("Los cambios de dispositivo detienen las pistas. El motor trabaja en estéreo, 44.1 kHz, entrada/salida PCM 16 bits y procesamiento float 32. MME no garantiza latencias de escenario. La compensación automática estima el desfase de entrada/salida; el ajuste en ms es una corrección adicional. El reloj entrante ajusta el tempo por cada grupo de 24 pulsos; no es un PLL de sincronización profesional.");
