Of(colors,staged.DubColor)),delegate{});Button appearance=Theme.Button("Guardar apariencia",delegate{engine.System.Indicator=indicator.SelectedItem.ToString();engine.System.RecordColor=recColor.SelectedItem.ToString();engine.System.PlayColor=playColor.SelectedItem.ToString();engine.System.DubColor=dubColor.SelectedItem.ToString();Storage.SaveSystem(engine.System);});appearance.Width=200;lg.Row("Aplicar",appearance);Button inferno=Theme.Button("PALETA INFERNO · ROSA / CORAL",delegate{recColor.SelectedItem="Coral";playColor.SelectedItem="Rosa";dubColor.SelectedItem="Ámbar";engine.System.RecordColor="Coral";engine.System.PlayColor="Rosa";engine.System.DubColor="Ámbar";Storage.SaveSystem(engine.System);app.ApplyAppearance();});inferno.Width=340;lg.Row("Colores de la referencia",inferno);
