  public void ShowInterface(){tabs.SelectedIndex=0;}
  public void ShowThemes(){tabs.SelectedIndex=5;}
  void BuildInterface(TabPage page){Panel scroll=new Panel{Dock=DockStyle.Fill,AutoScroll=true};page.Controls.Add(scroll);EditorGrid g=new EditorGrid();scroll.Controls.Add(g);g.Note("PERSONALIZA TU ESPACIO DE LOOP");g.Choice("Vista del loop",new string[]{"Pistas · controles y formas de onda","Escena Inferno · anillos y llamas"},engine.System.SceneMode?1:0,delegate(int v){app.SetLoopView(v==1);Storage.SaveSystem(engine.System);});g.Note("El loop conserva su lugar. Elige los controles de las cinco pistas o la escena animada en el mismo espacio. El audio y los atajos siguen funcionando al abrir Opciones.");g.Number("Intensidad del fuego (%)",engine.System.SceneIntensity*100,0,100,delegate(float v){engine.System.SceneIntensity=v/100;Storage.SaveSystem(engine.System);},0);Button open=Theme.Button("VOLVER AL LOOP",delegate{app.ShowMainPage(0);});open.Width=250;g.Row("Ver la interfaz elegida",open);Button themes=Theme.Button("ABRIR TEMAS E IDIOMA",ShowThemes);themes.Width=250;g.Row("Colores y personalización",themes);g.Note("Los temas, colores de los anillos y el idioma están en Temas / idioma. La vista Escena se configura aquí; ya no ocupa una pestaña del loop.");}
  TabPage Page(string title){TabPage p=new TabPage(title){BackColor=Theme.Background,ForeColor=Theme.Text};tabs.TabPages.Add(p);return p;}
  void Change(Action action){lock(engine.Gate){action();engine.Dirty=true;}}
  void BuildGeneral(){while(general.Controls.Count>0)general.Controls[0].Dispose();EditorGrid g=new EditorGrid();general.Controls.Add(g);SessionConfig c=engine.Config;Button direct=Theme.Button("INICIO DIRECTO AL PULSAR",delegate{engine.SetImmediateRecording();app.RefreshModel();});direct.Width=300;g.Row("Grabar sin espera musical",direct);Button clean=Theme.Button("PRUEBA LIMPIA · SIN FX",delegate{engine.SetCleanRecording();app.RefreshModel();});clean.Width=300;g.Row("Diagnosticar sonido",clean);g.Note("Prueba limpia conserva el audio, desactiva efectos y puerta de ruido, deja la ganancia al 100% y reproduce a velocidad normal. Úsala para comprobar si la toma suena fiel antes de añadir procesamiento.");g.Note("Inicio directo desactiva QUANTIZE, AUTO REC, la cuenta previa y la espera de compás de las pistas. La siguiente pulsación sobre una pista vacía comienza la grabación sin esperar al reloj musical.");g.Bool("Limpieza del micrófono",c.MicCleanup,delegate(bool v){Change(delegate{engine.Config.MicCleanup=v;});});g.Number("Filtro de aire / graves (Hz, 0 = apagado)",c.MicHighPass,0,300,delegate(float v){Change(delegate{engine.Config.MicHighPass=v;});},0);g.Number("Suavizar siseo (Hz, 0 = apagado)",c.MicLowPass,0,20000,delegate(float v){Change(delegate{engine.Config.MicLowPass=v;});},0);g.Number("Ruido de fondo: umbral (%)",c.MicNoiseThreshold*100,0,10,delegate(float v){Change(delegate{engine.Config.MicNoiseThreshold=v/100;});},2);g.Number("Reducción en pausas (dB)",c.MicReductionDb,0,36,delegate(float v){Change(delegate{engine.Config.MicReductionDb=v;});},0);g.Note("Limpieza actúa antes de grabar y en la monitorización. Empieza con 60–80 Hz para conservar bajos de beatbox. Aumentar el corte reduce golpes de aire pero también graves. El umbral atenúa ruido durante pausas con entrada rápida y salida suave; bájalo si pierdes sonidos suaves. No separa respiración y voz simultáneas. Desactivado conserva la entrada original; no repara tomas anteriores.");g.Number("Ganancia de entrada (%)",c.InputGain*100,0,400,delegate(float v){Change(delegate{engine.Config.InputGain=v/100;});},0);g.Number("Puerta de ruido (umbral %)",c.Gate*100,0,100,delegate(float v){Change(delegate{engine.Config.Gate=v/100;});},2);g.Number("Umbral de AUTO REC (%)",c.AutoThreshold*100,.01f,100,delegate(float v){Change(delegate{engine.Config.AutoThreshold=v/100;});},2);g.Bool("Silenciar entrada",c.InputMute,delegate(bool v){Change(delegate{engine.Config.InputMute=v;});});g.Bool("Monitorizar micrófono",c.Monitor,delegate(bool v){Change(delegate{engine.Config.Monitor=v;});});g.Bool("Compresor de entrada",c.InputCompressor,delegate(bool v){Change(delegate{engine.Config.InputCompressor=v;});});g.Number("Volumen máster (%)",c.Master*100,0,200,delegate(float v){Change(delegate{engine.Config.Master=v/100;});},0);g.Bool("Compresor máster",c.MasterCompressor,delegate(bool v){Change(delegate{engine.Config.MasterCompressor=v;});});g.Number("Reverb máster (%)",c.MasterReverb*100,0,100,delegate(float v){Change(delegate{engine.Config.MasterReverb=v/100;});},0);g.Number("EQ máster: graves (dB)",c.MasterLow,-20,20,delegate(float v){Change(delegate{engine.Config.MasterLow=v;});},1);g.Number("EQ máster: medios (dB)",c.MasterMid,-20,20,delegate(float v){Change(delegate{engine.Config.MasterMid=v;});},1);g.Number("EQ máster: agudos (dB)",c.MasterHigh,-20,20,delegate(float v){Change(delegate{engine.Config.MasterHigh=v;});},1);g.Choice("Modo de sincronización",new string[]{"Según QUANTIZE / ajuste de pista","Esperar al compás","Esperar longitud de loop"},c.SyncMode,delegate(int v){Change(delegate{engine.Config.SyncMode=v;});});g.Number("Longitud del loop (0 = AUTO)",c.LoopLengthBars,0,128,delegate(float v){Change(delegate{engine.Config.LoopLengthBars=(int)v;});},0);g.Bool("Limitador de salida",c.Limiter,delegate(bool v){Change(delegate{engine.Config.Limiter=v;});});g.Bool("Estimar tempo desde primera toma",c.AutoTempo,delegate(bool v){Change(delegate{engine.Config.AutoTempo=v;});});g.Bool("Cambiar velocidad al final del loop",c.SpeedChangeLoopEnd,delegate(bool v){Change(delegate{engine.Config.SpeedChangeLoopEnd=v;});});g.Bool("REC → DUB → PLAY",c.RecToDub,delegate(bool v){Change(delegate{engine.Config.RecToDub=v;});});g.Bool("SINGLE: cambiar al final del loop",c.SingleLoopEnd,delegate(bool v){Change(delegate{engine.Config.SingleLoopEnd=v;});});g.Note("Monitorizar la entrada puede causar realimentación con altavoces. Usa auriculares. El limitador reduce picos superiores a −0.18 dBFS. Los estados de transporte no se guardan: al recuperar una memoria las pistas quedan detenidas.");Button reset=Theme.Button("Restablecer ajustes de sistema",delegate{if(UiMessage.Show("¿Restablecer los dispositivos, indicadores y asignaciones? Las memorias guardadas se conservarán.","Restablecer sistema",MessageBoxButtons.YesNo)==DialogResult.Yes){app.ApplyDevices(new SystemConfig());UiMessage.Show("Ajustes restablecidos. Cierra y vuelve a abrir la app para actualizar los selectores de esta pantalla.");}});reset.Width=300;g.Row("Sistema",reset);}
  public void RefreshModel(){BuildGeneral();if(KeyboardOptions!=null)KeyboardOptions.Reload();}
  void Apply(){SystemConfig c=Storage.Clone(engine.System);c.InputDevice=audioIn.SelectedIndex==0?-1:audioIn.SelectedIndex==1?-2:audioIn.SelectedIndex-2;c.OutputDevice=audioOut.SelectedIndex-1;c.BufferFrames=buffer.SelectedIndex==0?256:buffer.SelectedIndex==2?1024:512;c.LatencyCompMs=(int)compensation.Value;c.AutoLatencyCompensation=autoLatency.Checked;c.MidiInput=midiIn.SelectedIndex-1;c.MidiOutput=midiOut.SelectedIndex-1;c.MidiChannel=(int)channel.Value;c.MidiClockIn=clockIn.Checked;c.MidiClockOut=clockOut.Checked;c.MidiThru=thru.Checked;app.ApplyDevices(c);staged=c;}
  static string[] Targets(){List<string> a=new List<string>();for(int i=1;i<=5;i++)foreach(string action in new string[]{"REC","STOP","UNDO","REDO","MARK","MARK BACK","CLEAR","LEVEL","PAN","MUTE","REVERSE","ONE SHOT","FX","SPEED"})a.Add("Pista "+i+" "+action);a.AddRange(new string[]{"Todos START","Todos STOP","Ritmo","Fill","Ritmo LEVEL","Input LEVEL","AUTO REC","QUANTIZE","SINGLE","Master","Tempo","Input FX A","Input FX B","Input FX C","Input FX D","Track FX A","Track FX B","Track FX C","Track FX D"});return a.ToArray();}
  void BuildAssignments(TabPage page){Panel root=new Panel{Dock=DockStyle.Fill};page.Controls.Add(root);FlowLayoutPanel buttons=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=65,Padding=new Padding(8)};root.Controls.Add(buttons);Button apply=Theme.Button("Aplicar asignaciones",SaveAssignments);apply.Width=175;buttons.Controls.Add(apply);Button learnButton=Theme.Button("Aprender CC de fila",delegate{SaveAssignments();int row=assignments.CurrentCell==null?0:assignments.CurrentCell.RowIndex;app.Midi.LearnIndex=row;learn=row;});learnButton.Width=175;buttons.Controls.Add(learnButton);Button cancel=Theme.Button("Cancelar aprendizaje",delegate{app.Midi.LearnIndex=-1;learn=-1;});cancel.Width=170;buttons.Controls.Add(cancel);Label help=Theme.Label("PC 0–98 → memorias 01–99. Notas GM → pads. CC → estas 16 asignaciones.");buttons.Controls.Add(help);
   assignments=new DataGridView{Dock=DockStyle.Fill,BackgroundColor=Theme.Background,BorderStyle=BorderStyle.None,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,RowHeadersWidth=48,EnableHeadersVisualStyles=false,EditMode=DataGridViewEditMode.EditOnEnter,GridColor=Theme.Line};assignments.DefaultCellStyle.BackColor=Theme.Panel;assignments.DefaultCellStyle.ForeColor=Theme.Text;assignments.DefaultCellStyle.SelectionBackColor=Color.FromArgb(45,66,78);assignments.ColumnHeadersDefaultCellStyle.BackColor=Theme.Background;assignments.ColumnHeadersDefaultCellStyle.ForeColor=Theme.Muted;assignments.Columns.Add(new DataGridViewCheckBoxColumn{Name="On",HeaderText="ON",FillWeight=40});assignments.Columns.Add("Channel","Canal");assignments.Columns.Add("CC","CC");DataGridViewComboBoxColumn target=new DataGridViewComboBoxColumn{Name="Target",HeaderText="Destino",FillWeight=250,FlatStyle=FlatStyle.Flat};target.Items.AddRange(Targets());assignments.Columns.Add(target);assignments.Columns.Add(new DataGridViewCheckBoxColumn{Name="Toggle",HeaderText="Toggle",FillWeight=60});assignments.Columns.Add("Min","Min (0–1)");assignments.Columns.Add("Max","Max (0–1)");for(int i=0;i<16;i++){Assignment m=engine.System.Assignments[i];int row=assignments.Rows.Add(m.Enabled,m.Channel,m.Controller,m.Target,m.Toggle,m.Min,m.Max);assignments.Rows[row].HeaderCell.Value=(i+1).ToString();}assignments.DataError+=delegate(object s,DataGridViewDataErrorEventArgs e){e.ThrowException=false;};root.Controls.Add(assignments);assignments.BringToFront();}
  void SaveAssignments(){assignments.EndEdit();Assignment[] maps=new Assignment[16];for(int i=0;i<16;i++){DataGridViewRow r=assignments.Rows[i];int ch,cc;float min,max;if(!int.TryParse(Convert.ToString(r.Cells[1].Value),out ch)||ch<1||ch>16||!int.TryParse(Convert.ToString(r.Cells[2].Value),out cc)||cc<0||cc>127||!float.TryParse(Convert.ToString(r.Cells[5].Value),out min)||!float.TryParse(Convert.ToString(r.Cells[6].Value),out max)||float.IsNaN(min)||float.IsNaN(max)||min<0||min>1||max<0||max>1)throw new Exception("Revisa canal, CC y rango de la fila "+(i+1)+".");maps[i]=new Assignment{Enabled=Convert.ToBoolean(r.Cells[0].Value),Channel=ch,Controller=cc,Target=Convert.ToString(r.Cells[3].Value),Toggle=Convert.ToBoolean(r.Cells[4].Value),Min=min,Max=max};}lock(engine.Gate)engine.System.Assignments=maps;Storage.SaveSystem(engine.System);}
  public void Tick(){midiStatus.Text=app.Midi.LastMessage+(app.Midi.LearnIndex>=0?" · Mueve un control MIDI para aprender CC "+(app.Midi.LearnIndex+1):"")+(app.Midi.Error==null?"":" · "+app.Midi.Error);if(learn>=0&&app.Midi.LearnIndex<0){Assignment m=engine.System.Assignments[learn];assignments.Rows[learn].Cells[0].Value=m.Enabled;assignments.Rows[learn].Cells[1].Value=m.Channel;assignments.Rows[learn].Cells[2].Value=m.Controller;learn=-1;}}
 }
